import React from 'react';
import loadable from '@loadable/component';
import { useLocation } from 'react-router-dom';
import { useCategory } from '@salesforce/commerce-sdk-react';
import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
import { HTTPError } from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors';
import Seo from '@salesforce/retail-react-app/app/components/seo';
import { Box, Skeleton, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import { categoryIdFromPathSegments, removeSiteLocaleFromPath } from '../../utils/url';

const fallback = <Skeleton height="75vh" width="100%" />;

// Loadable rather than static imports so this dispatcher stays a small chunk and the PLP and
// Experience pages keep the code-split boundaries routes.tsx already gives them.
const ProductList = loadable(() => import('../product-list'), { fallback });
const Experience = loadable(() => import('../experience'), { fallback });

const HTTP_NOT_FOUND = 404;
const HTTP_INTERNAL_SERVER_ERROR = 500;

/** The path segments of the current page with the site/locale prefix removed. */
export const pathSegments = (pathname: string): string[] =>
  removeSiteLocaleFromPath(pathname).split('/').filter(Boolean);

type CategoryPathProps = {
  /** Path segments to resolve; defaults to the current location. Exposed for tests. */
  segments?: readonly string[];
};

/**
 * Resolves a hierarchical storefront path (`/clothing/dresses/day-dresses`, SEO PRD DMU-014) to
 * the page that owns it. The segments joined with `-` are a category id by construction (see
 * `categoryUrlBuilder`), so one category lookup decides: found renders the PLP for that id; not
 * found with a single segment renders the Contentful experience page for that slug; anything
 * else is a 404. The PLP fetches the same category, and React Query serves it from this lookup.
 */
const CategoryPath = ({ segments: segmentsProp }: CategoryPathProps) => {
  const { pathname } = useLocation();
  const segments = segmentsProp ?? pathSegments(pathname);
  const categoryId = categoryIdFromPathSegments(segments);
  const { res } = useServerContext();
  const {
    data: category,
    isInitialLoading,
    error,
  } = useCategory({ parameters: { id: categoryId } }, { enabled: segments.length > 0 });

  if (category) {
    return <ProductList categoryId={categoryId} />;
  }

  if (isInitialLoading) {
    return fallback;
  }

  // Only a confirmed 404 means "not a category". Any other failure (Commerce API outage, auth)
  // is surfaced as an error rather than silently rendering a content page or a false 404 —
  // AGENTS.md > Graceful Degradation.
  const errorStatus = (error as { response?: { status?: number } } | null)?.response?.status;
  if (error && errorStatus !== HTTP_NOT_FOUND) {
    const status = errorStatus ?? HTTP_INTERNAL_SERVER_ERROR;
    throw new HTTPError(status, `HTTP Error ${status} occurred.`);
  }

  if (segments.length === 1) {
    return <Experience slug={segments[0]} />;
  }

  if (res) {
    res.status(HTTP_NOT_FOUND);
  }
  return (
    <>
      <Seo noIndex />
      <Box p={8}>
        <Text color="red.500">Page not found.</Text>
      </Box>
    </>
  );
};

CategoryPath.getTemplateName = () => 'category-path';

export default CategoryPath;

